// The interactive PhaseTripleProduct recursion figure (phasetripleproduct/index.html).
// Data: data/ptpfig.js, generated by scripts/gen_ptp_site.py: the reference policy's exact width
// ladder (computed by the Python mirror of PTP/Exact.lean), the k = 2 table of its third band with
// register contents computed by executing it, the interpolation weights solved from its points
// (and checked against the node identity numerically), and verbatim Lean statements.
// Three panels drawn as one SVG; every labelled element is clickable and opens a panel below the
// figure with the explanation and the Lean source. Same visual language as the PhaseProduct figure
// on the project page (ppfig.js, styles in ../site.css); this file draws three operands.
(function () {
  "use strict";
  var D = window.PTPFIG;
  var root = document.getElementById("ptpfig");
  if (!D || !root) return;
  var NS = "http://www.w3.org/2000/svg";
  var SUB = "₀₁₂₃₄₅₆₇₈₉";
  var SUP = "⁰¹²³⁴⁵⁶⁷⁸⁹";

  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; }); }
  function el(name, attrs, text) {
    var e = document.createElementNS(NS, name);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (text != null) e.textContent = text;
    return e;
  }
  function txt(parent, x, y, s, cls, anchor) {
    var t = el("text", { x: x, y: y, "class": cls || "pt", "text-anchor": anchor || "start" }, s);
    parent.appendChild(t); return t;
  }
  function node(id, x, y, w, h, lines, cls) {
    var g = el("g", { "class": "pn " + (cls || ""), "data-id": id, tabindex: "0", role: "button" });
    g.appendChild(el("rect", { x: x, y: y, width: w, height: h, rx: 6 }));
    var lh = 17, y0 = y + h / 2 - (lines.length - 1) * lh / 2 + 5;
    lines.forEach(function (l, i) {
      var c = typeof l === "string" ? { s: l } : l;
      txt(g, x + w / 2, y0 + i * lh, c.s, c.cls || (i === 0 ? "pt pt-b" : "pt"), "middle");
    });
    svg.appendChild(g);
    return g;
  }
  function arrow(x1, y1, x2, y2, cls) {
    svg.appendChild(el("line", { x1: x1, y1: y1, x2: x2, y2: y2, "class": cls || "pa", "marker-end": "url(#ptp-arrow)" }));
  }
  // "(B+B^2)/2" -> TeX
  function coeffTex(c) { return String(c).replace(/\^(\d+)/g, "^{$1}"); }
  function tex(u) {
    return "\\(" + String(u).replace(/−/g, "-").replace(/([+-])=/g, "\\mathrel{$1}=")
      .replace(/[₀-₉]/g, function (d) { return "_" + SUB.indexOf(d); }).replace(/∞/g, "\\infty") + "\\)";
  }

  var W = 1240, H = 584;
  var svg = el("svg", { viewBox: "0 0 " + W + " " + H, "class": "ppsvg", role: "img",
    "aria-label": "The PhaseTripleProduct recursion at k = 2; click any element for details" });
  svg.innerHTML = '<defs><marker id="ptp-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z"/></marker></defs>';
  root.appendChild(svg);

  // ------------------------------------------------------------ ① the policy
  var POL = D.policy;
  var nb = POL.bands.length;
  txt(svg, 12, 24, "① Policy", "pt ph");
  var card = el("g", { "class": "pcard" });
  card.appendChild(el("rect", { x: 10, y: 34, width: 300, height: 540, rx: 10 }));
  svg.appendChild(card);
  function rowBtn(id, x, y, w, s, cls, tx) {
    var g = el("g", { "class": "pn prow", "data-id": id, tabindex: "0", role: "button" });
    g.appendChild(el("rect", { x: x, y: y - 16, width: w, height: 23, rx: 4 }));
    txt(g, tx || x + 8, y, s, cls || "pt");
    svg.appendChild(g);
    return g;
  }
  rowBtn("policy", 16, 58, 288, "policy  P = ((w̲₁, T⁽¹⁾), (w̲₂, T⁽²⁾), …)", "pt pt-b");
  txt(svg, 160, 90, "Reference policy, n = " + POL.n + ", exact widths", "pt pt-b", "middle");
  txt(svg, 160, 108, nb + " bands; on width w use the first T⁽ʲ⁾ with w ≥ w̲ⱼ", "pt pt-s", "middle");
  var top = 120, rowH = 42, bx = 24, bw = 272;
  var bandY = [], y = top;
  POL.bands.forEach(function (b, bi) {
    var rows = POL.levels.filter(function (l) { return l.band === bi; });
    var h = Math.max(64, rows.length * rowH) + 24;
    var g = el("g", { "class": "pn pbandreg pbr" + (bi + 1), "data-id": "band" + (bi + 1), tabindex: "0", role: "button" });
    g.appendChild(el("rect", { x: bx, y: y, width: bw, height: h }));
    txt(g, bx + 6, y + 22, "T⁽" + "¹²³⁴⁵⁶"[bi] + "⁾", "pt pt-b");
    txt(g, bx + 6, y + 40, "k = " + b.k, "pt pt-b");
    txt(g, bx + 6, y + 56, bi === 0 ? "w ≥ " + b.threshold : (b.threshold + " ≤ w < " + POL.bands[bi - 1].threshold), "pt pt-s");
    if (!rows.length) txt(g, bx + 112, y + 42, "not reached from n", "pt pt-s");
    svg.appendChild(g);
    bandY.push(y); y += h;
  });
  var base = POL.bands[nb - 1].threshold;
  var gbase = el("g", { "class": "pn pbandreg pbr0", "data-id": "base", tabindex: "0", role: "button" });
  gbase.appendChild(el("rect", { x: bx, y: y, width: bw, height: 72 }));
  txt(gbase, bx + 6, y + 38, "base case", "pt pt-b");
  txt(gbase, bx + 6, y + 56, "w < " + base, "pt pt-s");
  svg.appendChild(gbase);
  var baseY = y;
  var ry = {};
  POL.levels.forEach(function (l, i) {
    var before = POL.levels.filter(function (m, j) { return j < i && m.band === l.band; }).length;
    var y0 = (l.band >= 0 ? bandY[l.band] : baseY) + 18 + before * rowH;
    ry[i] = y0;
    var g = el("g", { "class": "pn pwrow", "data-id": "width", tabindex: "0", role: "button" });
    g.appendChild(el("rect", { x: 112, y: y0, width: 176, height: 30, rx: 6 }));
    txt(g, 120, y0 + 20, "w" + SUB[i] + (i === 0 ? " = n = " : " = ") + l.w, "pt pt-m");
    txt(g, 280, y0 + 20, l.k ? "k" + SUB[i] + " = " + l.k : "leaf", "pt pt-m", "end");
    svg.appendChild(g);
    if (i > 0) arrow(200, ry[i - 1] + 30, 200, y0 - 1, "pa pa-thin");
  });
  POL.bands.forEach(function (b, bi) {
    var yl = bi + 1 < nb ? bandY[bi + 1] : baseY;
    svg.appendChild(el("line", { x1: bx, y1: yl, x2: bx + bw, y2: yl, "class": "pthr" }));
    var g = el("g", { "class": "pn pthrlab", "data-id": "thr", tabindex: "0", role: "button" });
    g.appendChild(el("rect", { x: bx + bw - 82, y: yl - 10, width: 78, height: 20, rx: 10 }));
    txt(g, bx + bw - 43, yl + 5, "w̲" + SUB[bi + 1] + " = " + b.threshold, "pt pt-s pt-thr", "middle");
    svg.appendChild(g);
  });
  var gf = el("g", { "class": "pn prow", "data-id": "width", tabindex: "0", role: "button" });
  gf.appendChild(el("rect", { x: 16, y: baseY + 84, width: 288, height: 44, rx: 4 }));
  txt(gf, 160, baseY + 102, "(k₀, k₁, …) = (" + POL.levels.filter(function (l) { return l.k; }).map(function (l) { return l.k; }).join(", ") + ")", "pt pt-b", "middle");
  txt(gf, 160, baseY + 121, "wᵢ₊₁ = ptpTightWidth(Tᵢ, wᵢ) < wᵢ", "pt pt-b", "middle");
  svg.appendChild(gf);

  // ------------------------------------------------------------ ② one level
  var K = D.k, Q = D.q;
  var tg = el("g", { "class": "pn ptitle", "data-id": "prog", tabindex: "0", role: "button" });
  tg.appendChild(el("rect", { x: 334, y: 6, width: 580, height: 26, rx: 4 }));
  txt(tg, 340, 24, "② T⁽³⁾ (k = " + K + "):  PTP(φxyz) → 3k − 2 = " + Q + " PhaseTripleProducts", "pt ph");
  svg.appendChild(tg);
  function uName(id) { return "Π⁽" + "⁰¹²"[+id.slice(1)] + "⁾"; }
  var wy = function (w) { return 64 + w * 50; };           // wires x0 y0 z0 x1 y1 z1
  var names = ["x₀", "y₀", "z₀", "x₁", "y₁", "z₁"];
  for (var w = 0; w < 6; w++) {
    svg.appendChild(el("line", { x1: 362, y1: wy(w), x2: 904, y2: wy(w), "class": "pw" }));
    txt(svg, 356, wy(w) + 5, names[w], "pt pt-w", "end");
    txt(svg, 910, wy(w) + 5, names[w], "pt pt-w");
  }
  var cols = { U0: 372, PP1: 456, U1: 598, PP2: 680, U2: 822 };
  var segU = {}, ppIdx = 0, ppGroup = 0;
  D.segments.forEach(function (s) {
    if (s.kind === "U") {
      segU[s.name] = s;
      var x = cols[s.name];
      // one bar per operand, from its register 0 to its register 1: the same ops act on all three
      for (var o = 0; o < 3; o++) {
        var g = node(s.name, x + o * 25, wy(o) - 12, 22, wy(3 + o) - wy(o) + 24, [], "pu");
        txt(g, x + o * 25 + 11, wy(o) + 2, "xyz"[o], "pt pt-pi", "middle");
      }
      txt(svg, x + 36, wy(0) - 22, uName(s.name), "pt pt-b", "middle");
    } else {
      var p = D.pps[ppIdx++];
      var grp = p.n <= 2 ? 1 : 2;
      var x0 = grp === 1 ? cols.PP1 : cols.PP2;
      var top2 = wy(3 * p.reg) - 20, h = wy(3 * p.reg + 2) - wy(3 * p.reg) + 40;
      var g2 = node("pp" + p.n, x0, top2, 134, h,
        [{ s: "PTP at p = " + p.point, cls: "pt pt-b" }, { s: "x: " + p.x, cls: "pt pt-m" }, { s: "y: " + p.y, cls: "pt pt-m" }, { s: "z: " + p.z, cls: "pt pt-m" }], "ppp");
      var c = el("g", { "class": "pnum" });
      c.appendChild(el("circle", { cx: x0 + 4, cy: top2 + 2, r: 11 }));
      txt(c, x0 + 4, top2 + 7, String(p.n), "pt pt-n", "middle");
      g2.appendChild(c);
    }
  });
  var band = [{ id: "U0", x: 340, w: 150 }, { id: "U1", x: 496, w: 250 }, { id: "U2", x: 752, w: 150 }];
  band.forEach(function (b) {
    var s = segU[b.id];
    var g = el("g", { "class": "pn pband", "data-id": b.id, tabindex: "0", role: "button" });
    g.appendChild(el("rect", { x: b.x, y: 368, width: b.w, height: 84, rx: 6 }));
    txt(g, b.x + 10, 390, uName(b.id) + ":", "pt pt-b");
    s.math.forEach(function (m, i) { txt(g, b.x + 10, 410 + i * 18, m, "pt pt-m"); });
    svg.appendChild(g);
  });
  txt(svg, 340, 474, "rⱼ = (xⱼ, yⱼ, zⱼ): each op acts on the x, y and z limbs alike", "pt pt-s");
  var strip = el("g", { "class": "pn pstrip", "data-id": "prog", tabindex: "0", role: "button" });
  strip.appendChild(el("rect", { x: 340, y: 486, width: 562, height: 30, rx: 6 }));
  txt(strip, 352, 506, "T⁽³⁾:  Π⁽⁰⁾ → p = " + D.points.slice(0, 2).join(", ") + " → Π⁽¹⁾ → p = " + D.points.slice(2).join(", ") + " → Π⁽²⁾", "pt");
  svg.appendChild(strip);

  // ------------------------------------------------------------ ③ recursion
  txt(svg, 930, 24, "③ Recursive PTP blocks", "pt ph");
  D.pps.forEach(function (p, i) {
    var yy = 60 + i * 60;
    node("child", 930, yy, 92, 40, ["PTP at " + p.point], "pchild");
    var c = el("g", { "class": "pnum" });
    c.appendChild(el("circle", { cx: 930, cy: yy, r: 10 }));
    txt(c, 930, yy + 5, String(p.n), "pt pt-n", "middle");
    svg.appendChild(c);
    for (var t = -1; t <= 1; t++) arrow(1023, yy + 20, 1046, yy + 20 + t * 9, "pa pa-thin");
    node("child", 1048, yy, 92, 40, [Q + " PTPs", { s: "via T⁽³⁾", cls: "pt pt-s" }], "pchild");
    txt(svg, 1153, yy + 25, "…", "pt pt-b", "middle");
  });
  node("base", 1168, 60, 66, 220, ["base", "case", "", "sandwich", "leaves"], "pbase");
  txt(svg, 1090, 312, "sum over nodes", "pt pt-s", "middle");
  txt(svg, 1090, 328, "(arithmetic + leaves)", "pt pt-s", "middle");
  arrow(1200, 284, 1200, 410);
  node("bound", 930, 410, 304, 94,
    [{ s: "Output: gate count of PTP(φxyz)", cls: "pt pt-b" },
     { s: "Lean, constant policy:", cls: "pt pt-m" },
     { s: "O(n^(log_k(3k−2))) gates", cls: "pt pt-m" },
     { s: "k = 2: n², not n³", cls: "pt pt-s" }], "pout");

  // ------------------------------------------------------------ detail panels
  var S = D.snippets;
  function code(s, label) {
    var h = '<p class="lsnip-head"><code>' + esc(s.name) + "</code> · " +
      '<a href="' + D.repo + "/" + D.root + "/" + s.file + "#L" + s.line + '">' + esc(s.file) + ":" + s.line + "</a></p>";
    h += '<pre class="lsnip lean"><code>' + (window.leanHL ? window.leanHL(s.code) : esc(s.code)) + "</code></pre>";
    if (label) h += '<p class="lsnip-note">' + label + "</p>";
    return h;
  }
  function stateTable(s) {
    var h = '<table class="pstate"><tr><th></th><th>before</th><th>after</th></tr>';
    for (var i = 0; i < s.before.length; i++)
      h += "<tr><td>\\(r_" + i + "\\)</td><td>" + tex(s.before[i]) + "</td><td>" + tex(s.after[i]) + "</td></tr>";
    return h + "</table>";
  }
  function uPanel(id) {
    var s = segU[id], n = "\\(\\Pi^{(" + id.slice(1) + ")}\\)";
    var t = "<p>" + n + " is the arithmetic between two rounds of phase products: " + s.math.length +
      " in-place addition" + (s.math.length > 1 ? "s" : "") + " of one limb register into another. Each is applied to the \\(x\\), \\(y\\) and \\(z\\) limbs alike, " +
      "so the node emits <em>three</em> gates per operation (<code>opGates</code>). In order: " + s.math.map(tex).join(", ") + ".</p>" +
      stateTable(s) +
      "<p>Written \\(x_0, x_1\\) for the two limbs of \\(x\\), and likewise for \\(y\\) and \\(z\\). " +
      (id === "U2" ? "\\(\\Pi^{(2)}\\) brings every register back to its own limb: the program ends where it started (<code>returnsToStartCheck</code> in the contract), so the workspace is returned clean." :
        "The columns are computed by running the table, not typed in.") + "</p>";
    return { title: n, role: "register arithmetic", text: t,
      code: '<p class="lsnip-head">the same operations, as in the policy file</p><pre class="lsnip lean"><code>' +
        window.leanHL(D.tableOps.filter(function (o) { return o[0] !== "phaseProduct"; })
          .map(function (o) { return "addScaled dst=" + o[1] + " src=" + o[2] + " sign=" + o[3] + " shift=" + o[4]; }).join("\n")) +
        "</code></pre>" + code(S.ptpSubNode) };
  }
  function ppPanel(n) {
    var p = D.pps[n - 1];
    var t = "<p>Phase triple product " + n + " of " + Q + ", taken on limb register \\(r_" + p.reg + "\\), which at this moment holds " +
      tex(p.x) + " for \\(x\\), " + tex(p.y) + " for \\(y\\) and " + tex(p.z) + " for \\(z\\): the three limb polynomials evaluated at " +
      tex("p = " + p.point) + (p.point === "∞" ? " (at infinity, the leading coefficient)" : "") + ".</p>" +
      "<p>The contract requires that match: <code>progConsumesPts?</code> walks the program and at every <code>phaseProduct i</code> takes the " +
      "next point and checks register \\(i\\) against its row, here <code>[" + p.row.join(", ") + "]</code>.</p>" +
      "<p>The angle is not \\(\\varphi\\) but \\(\\varphi\\,c_" + (n - 1) + "\\) with \\(c_" + (n - 1) + " = " + coeffTex(p.coeff) +
      "\\), where \\(B = 2^{w}\\) is the radix of the limbs (<code>PTPTable.coeff</code>). The " + Q + " weights are solved from the points, " +
      "and <code>node_identity</code> says \\(\\sum_t c_t \\prod_s x_s(p_t) = x_0 x_1 x_2\\), so the " + Q + " phases multiply out to " +
      "\\(\\exp(i\\pi\\varphi\\,xyz)\\). The identity was re-checked here by exact arithmetic on this table for random limbs. " +
      "The product itself is a smaller phase triple product, which recurses (panel ③).</p>";
    return { title: "\\(\\mathrm{PTP}\\) at " + tex("p = " + p.point), role: "one of the " + Q + " smaller products", text: t,
      code: code(S.node_identity) + code(S.PTPTable_contract || S.contract) };
  }
  var P = {
    k: function () { return { title: "\\(k = " + K + "\\)", role: "the arity", text:
      "<p>Each of the three operands is split into \\(k\\) limbs of about \\(n/k\\) bits. The product of three degree-\\((k-1)\\) limb polynomials " +
      "has degree \\(3(k-1)\\), so it is fixed by its values at \\(3(k-1)+1 = 3k-2\\) points: here " + Q + " phase triple products on limb-sized registers replace one at full width.</p>" +
      "<p>The exponent is \\(\\log_k(3k-2)\\): \\(2.000\\) at \\(k=2\\) (a cubic phase brought down to a quadratic count, no further), \\(1.771\\) at \\(k=3\\), \\(1.661\\) at \\(k=4\\), tending to 1.</p>",
      code: code(S.pointCount) + code(S.ptpExponent) }; },
    prog: function () { return { title: "The table", role: "a straight-line program on k limb registers", text:
      "<p>The same program language as PhaseProduct: <code>addScaled</code>, <code>negate</code>, <code>shiftL</code>, <code>shiftR</code>, and " +
      "<code>phaseProduct i</code> checkpoints. What changes is the point count and what a checkpoint means: " + Q + " points, and each checkpoint is taken on three operands at once.</p>" +
      "<p>The table drawn here is the third band of <code>" + esc(D.policyFile) + "</code> (\\(k = 2\\), " + D.arithmetic + " arithmetic operations in " + D.layers + " layers, " +
      "benchmark score \\(" + D.arithmetic + " + 5\\cdot " + D.layers + " = " + D.score + "\\), which equals the champion for <code>PhaseTripleProduct</code> \\(k=2\\) in <code>leaderboard/best-known.md</code>). " +
      "Its register contents were computed by executing it here with a direct mirror of the Lean definitions; the policy that contains it is accepted by the fork's PTP policy checker, which is not part of this development.</p>",
      code: '<p class="lsnip-head">this figure\'s program, as in the policy file</p><pre class="lsnip lean"><code>' +
        window.leanHL(D.tableOps.map(function (o) { return o.join(" "); }).join("\n")) + "</code></pre>" + code(S.PTPTable_contract || S.contract) }; },
    U0: function () { return uPanel("U0"); }, U1: function () { return uPanel("U1"); }, U2: function () { return uPanel("U2"); },
    width: function () {
      var lv = POL.levels.map(function (l, i) { return "\\(w_" + i + " = " + l.w + "\\)" + (l.k ? " (\\(k = " + l.k + "\\))" : " (base case)"); }).join(", ");
      var sc = POL.scan.map(function (l) { return l.w + (l.k ? " (k=" + l.k + ")" : ""); }).join(" → ");
      return { title: "Widths per level", role: "\\(w_{i+1} = \\mathtt{ptpTightWidth}(T_i, w_i) < w_i\\)", text:
      "<p>Each level is one operand width. The policy looks at it, picks a table, and the table's arithmetic fixes the next width: <code>ptpTightWidth</code> is the " +
      "<em>least</em> width that holds every value the program produces, proved sound and minimal (<code>ptpTightWidth_spec</code>, <code>tight_minimal</code>).</p>" +
      "<p>For this policy at \\(n = " + POL.n + "\\), the exact ladder is " + lv + ". This is <code>ladderX</code> (quoted on the right), computed here by a Python mirror of the Lean definitions; the ShorTableOptimization fork's policy checker (not part of this development) has the kernel recompute and decide the same ladder when it checks the policy. " +
      "Note that the second band, \\(k=4\\), is never used: at exact widths the first child width, 375, is below its threshold of 398.</p>" +
      "<p>The conservative <em>scan</em> board gives a different ladder, " + sc + ", because its widths are larger and so land in different bands. Both boards are proved; the headline theorem and the gate-count theorem use the exact one.</p>",
      code: code(S.ptpTightWidth_spec || S.ptpTightWidth) + code(S.ladderX) + code(S.childWidth3)}; },
    policy: function () { return { title: "A policy", role: "a table for each range of widths", text:
      "<p>A policy is a list of bands \\((\\underline{w}_j, T^{(j)})\\), widest first, with strictly decreasing thresholds. At width \\(w\\), <code>choose</code> returns the table " +
      "of the first band whose threshold is at most \\(w\\); below the last threshold it returns <code>none</code> and the node takes the leaf. The node also takes the leaf if the table " +
      "would not shrink the width.</p>" +
      "<p><code>PTPPolicy.check</code> accepts a policy when thresholds strictly decrease and every table passes the contract; the stronger <em>acceptance rule</em> (<code>chainContractsTight</code>) also requires that every band the recursion reaches shrinks the width and applies at a width of at least \\(k\\).</p>",
      code: code(S.choose) + code(S.check) }; },
    thr: function () { return { title: "Thresholds", role: "\\(\\underline{w}_1 > \\underline{w}_2 > \\cdots\\)", text:
      "<p>The underlined \\(\\underline{w}_j\\) are the policy's thresholds: " + POL.bands.map(function (b, i) { return "\\(\\underline{w}_" + (i + 1) + " = " + b.threshold + "\\)"; }).join(", ") +
      ". The plain \\(w_i\\) are the widths the recursion actually reaches. A policy is keyed on width, not depth, because the width at depth 3 depends on the choices at depths 1 and 2.</p>",
      code: code(S.check) + code(S.choose) }; },
    base: function () { return { title: "Base case", role: "the sandwich leaf", text:
      "<p>Where the policy has no table, or the table would not shrink the width, the recursion stops at a leaf: the compute–rotate–uncompute <code>ptpLeafSandwich</code>. " +
      "For each bit of \\(x\\) it Toffolis the product of a bit of \\(y\\) and a bit of \\(z\\) into a clean ancilla, rotates once with the signed bit weight, and uncomputes; " +
      "one rotation per cell instead of five for the doubly-controlled-phase leaf kept as an alternative.</p>" +
      "<p>The recursion itself is <code>PolicyImpl</code>, an inductive family of gate-level circuits following a policy.</p>",
      code: code(S.PolicyImpl) }; },
    child: function () { return { title: "Recursive PTP blocks", role: "each child is lowered again", text:
      "<p>Each of the " + Q + " products in panel ② is itself a phase triple product of the next width and is lowered the same way. In <code>PolicyImpl</code> a node carries one child recursion per slot triple, " +
      "all sharing one workspace pool, run one after another.</p>" +
      "<p>Correctness holds at every depth for every checked policy: <code>ptp_gate_full_exact</code> gives the circuit, its gate counts and a qubit bound; <code>ptp_lowerExact_correct</code> says it acts as the specification on every clean state.</p>",
      code: code(S.evalL_ptpNode_ket) + code(S.ptp_gate_full_exact) }; },
    bound: function () { return { title: "The gate count", role: "constant policy: \\(O(n^{\\log_k(3k-2)})\\)", text:
      "<p>A node of width \\(w\\) costs its own arithmetic, linear in \\(w\\), plus " + Q + " children of width at most \\(\\lfloor w/k\\rfloor + k + D\\), where \\(D\\) is the total shift and add growth of the program. " +
      "With one table at every width that recurrence solves to \\(C\\cdot n^{\\log_k(3k-2)}\\) by ForShor's shifted master theorem; <code>ptp_circuit_gateCount_bound</code> states it for the constructed circuit.</p>" +
      "<p>The statement is for a <strong>constant policy</strong>, as in ForShor, and the count is <code>rz + toffoli + x + h + cnot</code> under <code>shorGateResourceModel</code>, not a T count. " +
      "It is a bound on a classical object (the census of a circuit), not a claim about any factoring cost: PTP is not used by ForShor's order-finding circuit.</p>",
      code: code(S.ptpExponent) + code(S.PTPGateTotalBound) + code(S.ptp_lowerExact_correct) }; },
  };
  for (var i = 1; i <= D.pps.length; i++) (function (n) { P["pp" + n] = function () { return ppPanel(n); }; })(i);
  for (var j = 1; j <= nb; j++) (function (n) {
    P["band" + n] = function () {
      var b = POL.bands[n - 1], reached = POL.levels.filter(function (l) { return l.band === n - 1; });
      return { title: "\\(T^{(" + n + ")}\\) band", role: "\\(k = " + b.k + ",\\ " + (n === 1 ? "w \\ge " + b.threshold : b.threshold + " \\le w < " + POL.bands[n - 2].threshold) + "\\)", text:
        "<p>Band " + n + " of " + nb + ": a \\(k = " + b.k + "\\) table with " + (3 * b.k - 2) + " points, so each node of this band splits into " + (3 * b.k - 2) + " smaller phase triple products. " +
        (reached.length ? "From \\(n = " + POL.n + "\\) the recursion applies it at width" + (reached.length > 1 ? "s " : " ") + reached.map(function (l) { return l.w; }).join(" and ") + "." :
          "From \\(n = " + POL.n + "\\) the exact recursion never lands in this band; it would apply at widths from " + b.threshold + " up to " + (POL.bands[n - 2].threshold - 1) + ".") +
        (n === 3 ? " Panel ② draws this band's table." : "") + "</p>" +
        "<p>The bands of the reference policy are the benchmark's golden reference, with <code>" + esc(D.policyFile) + "</code> the file.</p>",
        code: code(S.choose) + code(S.check) };
    };
  })(j);

  // ------------------------------------------------------------ interaction
  var panel = document.createElement("div");
  panel.className = "ldetail ppdetail";
  root.appendChild(panel);
  var openId = null;
  function mark(id) {
    svg.querySelectorAll(".pn").forEach(function (g) { g.classList.toggle("on", g.getAttribute("data-id") === id); });
  }
  function show(id, instant) {
    if (openId === id) { openId = null; mark(null); panel.classList.remove("open"); setHash(null); return; }
    var d = P[id]();
    openId = id; mark(id);
    if (window.clearMath) window.clearMath(panel);
    panel.innerHTML = '<div class="ldetail-inner"><div class="ldetail-grid"><div class="ldetail-text"><h3>' + esc(d.title) +
      ' <span class="lrole">' + esc(d.role) + "</span></h3>" + d.text +
      '<p><a href="#layer-Gates">The gate layers in the graph above</a></p></div><div class="ldetail-code">' +
      d.code + "</div></div></div>";
    if (instant) panel.classList.add("instant");
    void panel.offsetHeight;
    panel.classList.add("open");
    if (window.typesetMath) window.typesetMath(panel);
    setHash(id);
  }
  function setHash(id) {
    if (!window.history || !history.replaceState) return;
    history.replaceState(null, "", location.pathname + location.search + (id ? "#ptpfig-" + id : ""));
  }
  svg.querySelectorAll(".pn").forEach(function (g) {
    var id = g.getAttribute("data-id");
    g.addEventListener("click", function () { show(id); });
    g.addEventListener("keydown", function (e) { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); show(id); } });
  });
  var m = /^#ptpfig-([A-Za-z0-9]+)$/.exec(location.hash || "");
  if (m && P[m[1]]) { show(m[1], true); setTimeout(function () { if (root.scrollIntoView) root.scrollIntoView({ block: "start" }); }, 0); }
})();
